<?php
require __DIR__.'/../config.php';require __DIR__.'/../report_helpers.php';$u=require_admin();if(!is_general_admin($u)){http_response_code(403);exit('Somente o Admin Geral.');}$pdo=db();$testId=(int)($_GET['test_id']??0);$test=evaluation_test($testId);if(!$test||!evaluation_report_is_visible_to_admin($test)){http_response_code(404);exit('Relatório final não encontrado ou ainda não enviado pelo instrutor.');}
$owner=evaluation_test_owner($testId);$area=evaluation_test_primary_area($testId);
$sql="SELECT e.id,e.student_name,e.preferred_name,e.registration_number,s.area,ROUND(AVG(s.final_score),1) final_score FROM evaluation_submissions s JOIN enrollments e ON e.id=s.student_id WHERE s.test_id=? AND s.status='CONCLUIDA' GROUP BY e.id,s.area ORDER BY s.area,e.student_name COLLATE NOCASE";$st=$pdo->prepare($sql);$st->execute([$testId]);$rows=$st->fetchAll();
if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="avaliacao_final_bamab_'.date('Ymd').'.csv"');echo "\xEF\xBB\xBF";$out=fopen('php://output','w');fputcsv($out,['NOME','MATRÍCULA/CÓDIGO','INSTRUMENTO/ALA','NOTA FINAL'],';');foreach($rows as $r)fputcsv($out,[evaluation_student_name($r),$r['registration_number'],$r['area'],number_format((float)$r['final_score'],1,',','.')],';');fclose($out);exit;}
$ownerName=$owner?instructor_display_name($owner):'Registro legado';$sent=(string)($test['submitted_to_admin_at']??'');
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Relatório Final de Avaliação</title><link rel="stylesheet" href="../assets/report_a4.css"><?=bamab_report_style_block('../')?><style>.eval-report-note{padding:3mm 4mm;border:1px solid #bca25c;background:#fff9e9;color:#282014;margin:4mm 0;font-size:9pt}.eval-score{text-align:center;font-weight:900;font-size:11pt}.eval-meta{display:grid;grid-template-columns:repeat(3,1fr);gap:3mm;margin:4mm 0}.eval-meta div{border:1px solid #c9b67e;background:#fffdf7;padding:3mm}.eval-meta span{display:block;font-size:7.5pt;color:#6b5a32;text-transform:uppercase;font-weight:800}.eval-meta strong{display:block;margin-top:1mm;color:#17130c}.eval-sign{display:grid;grid-template-columns:1fr 1fr;gap:14mm;margin-top:18mm}.eval-sign div{text-align:center}.eval-sign span{display:block;border-top:1px solid #222;margin-bottom:2mm}@media(max-width:700px){.eval-meta{grid-template-columns:1fr}}</style></head><body><div class="a4-toolbar no-print"><a href="avaliacoes.php">← VOLTAR</a><button onclick="window.print()">IMPRIMIR / PDF A4</button><a href="?test_id=<?=$testId?>&export=csv">CSV</a></div><main class="a4-document"><header class="a4-header"><img src="<?=e(bamab_report_logo_web('../'))?>" alt="Brasão"><div class="a4-location"><?=e(report_location_line())?></div></header><section class="a4-title"><h1>RELATÓRIO FINAL DE AVALIAÇÃO</h1><p><?=e($test['title'])?></p></section><div class="eval-meta"><div><span>Instrutor responsável</span><strong><?=e($ownerName)?></strong><?php if($owner&&!empty($owner['instructor_code'])):?><small><?=e($owner['instructor_code'])?></small><?php endif;?></div><div><span>Instrumento / Ala</span><strong><?=e($area?:'—')?></strong></div><div><span>Data de conclusão</span><strong><?=e($sent!==''?date('d/m/Y H:i',strtotime($sent)):date('d/m/Y',strtotime($test['test_date'])))?></strong></div></div><div class="eval-report-note">Este é o relatório final enviado pelo instrutor. O Admin recebe somente as notas finais. Os 10 critérios e pontuações individuais permanecem registrados na área interna do instrutor.</div><section class="a4-section"><table class="a4-table"><thead><tr><th>Nome</th><th>Matrícula / Código</th><th>Instrumento / Ala</th><th>Nota Final</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e(evaluation_student_name($r))?></td><td><?=e($r['registration_number'])?></td><td><?=e($r['area'])?></td><td class="eval-score"><?=e(evaluation_score_text((float)$r['final_score']))?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="4">Nenhuma avaliação concluída foi enviada neste relatório.</td></tr><?php endif;?></tbody></table></section><section class="eval-sign"><div><span></span><strong>INSTRUTOR RESPONSÁVEL</strong></div><div><span></span><strong>COORDENAÇÃO GERAL</strong></div></section><footer class="a4-footer">Relatório final BAMAB · gerado em <?=date('d/m/Y H:i')?>.</footer></main></body></html>
